def build(p):
    import cadquery as cq
    out = None
    for a in (0, 90, 180):
        x, z = p['R_station'] * math.cos(math.radians(a)), -p['R_station'] * math.sin(math.radians(a))
        d = cq.Workplane("XZ").circle(p['D'] / 2).extrude(-p['t']).translate((x, -p['t'] - 3, z))
        out = d if out is None else out.union(d)
    return out
